def _evidence_fields(data):
    """Strict wire walk for optional motion evidence; normal UI decoding stays unchanged."""
    fields, pos = {}, 0

    def varint():
        nonlocal pos
        value = 0
        for i in range(10):
            if pos >= len(data):
                raise ValueError()
            b = data[pos]
            pos += 1
            value |= (b & 127) << (7 * i)
            if not b & 128:
                if i == 9 and b > 1:
                    raise ValueError()
                return value
        raise ValueError()

    try:
        while pos < len(data):
            tag = varint()
            number, wire = tag >> 3, tag & 7
            if number == 0:
                return None
            if wire == 0:
                value = varint()
            elif wire in (1, 2, 5):
                size = varint() if wire == 2 else (8 if wire == 1 else 4)
                if size > len(data) - pos:
                    return None
                value = data[pos:pos + size]
                pos += size
            else:
                return None
            fields.setdefault(number, []).append((wire, value))
    except ValueError:
        return None
    return fields


def _mark_motion_evidence(ret, cmd, payload):
    # Called only after CRC, frame length and response flag passed.
    if cmd not in (6, 73, 76):
        return
    fields = _evidence_fields(payload)
    result = ret.get('result') or {}
    ret.update(_v2_frame_valid=True, _v2_command=cmd, _v2_payload_valid=False)
    if fields is None:
