        # Protobuf defaults can omit zero steps/length/state; the row
        # itself must be real. An absent decoder is not a measurement.
        if cmd == 6:
            state = sub.get(1, [(0, 0)])
            row['_wire_valid'] = (len(state) == 1 and state[0][0] == 0
